# Generated by build.py from recipe.yml for recipe sftp-offer-weak-algorithms-for-old-clients. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'old' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'old/hello.txt'), "hello from an old surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'get.sftp'), "get hello.txt got.txt`n")
cmd /c 'ssh-keygen -t rsa -b 3072 -N "" -f host_key'
cmd /c 'ssh-keygen -t rsa -b 1024 -N "" -f old_key'
cmd /c 'ssh-keygen -t ed25519 -N "" -f client_key'
$server0 = Start-Process surl -ArgumentList '--allow-weak-ssh-algorithms', '--directory', 'site', '--hostkey', 'host_key', '--authorized-keys', 'alice:client_key.pub', 'sftp://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { sftp -q -b get.sftp -P 8081 -i client_key -o Ciphers=aes128-cbc -o StrictHostKeyChecking=no -o UserKnownHostsFile=NUL -o GlobalKnownHostsFile=NUL alice@127.0.0.1 } finally { Stop-Process $server0 }
